package com.muxigame.city;

import java.util.*;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.commands.Commands;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.level.block.*;
import net.minecraft.nbt.CompoundTag;
import net.neoforged.neoforge.network.PacketDistributor;

/** Admin fixture and compact control surface. Never resets an existing city or grants funds on binding. */
public final class CityTradeLab {
 static void attach(MinecraftServer s,CityData.City c,RuralSettlement.Site site,RuralRules.Person person){if(!Set.of("procurement","baker","supplier").contains(site.kind))return;var t=CityTrade.get(s);if(!t.state.towns.containsKey(c.id))return;var b=t.state.businesses.values().stream().filter(v->v.worker.equals(person.id)).findFirst().orElseGet(()->{var v=new CityTrade.Business();v.id=UUID.randomUUID();v.worker=person.id;v.city=c.id;v.account="trade:"+v.id;t.state.businesses.put(v.id,v);return v;});b.site=site.pos;b.kind=site.kind;t.setDirty();}
 static void register(com.mojang.brigadier.CommandDispatcher<net.minecraft.commands.CommandSourceStack> dispatcher){CityDataTemplate.register(dispatcher);dispatcher.register(Commands.literal("citytrade").requires(s->s.hasPermission(2)).executes(c->{snapshot(c.getSource().getPlayerOrException(),"");return 1;})
  .then(Commands.literal("create").executes(c->{UUID id=create(c.getSource().getServer());c.getSource().sendSuccess(()->Component.literal("有限经济样板已创建："+id+"；用citytrade start开始30日，不重复初始化"),true);return 1;}))
  .then(Commands.literal("start").executes(c->{CityTrade.get(c.getSource().getServer()).start(c.getSource().getServer());c.getSource().sendSuccess(()->Component.literal("30倍、30游戏日观察已开始"),true);return 1;}))
  .then(Commands.literal("observe").executes(c->{var s=c.getSource().getServer();var t=CityTrade.get(s);CityEconomy.require(t.state.run.done&&!t.state.run.running,"仅完成前一窗口后可续测，不重置人物和资产");var old=t.state.run;try{var dir=s.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("city_settlements/finite-economy");java.nio.file.Files.copy(dir.resolve("latest.json"),dir.resolve("window-"+old.startClock+".json"),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}catch(java.io.IOException ex){throw new IllegalArgumentException("无法保留上一窗口报告",ex);}long gap=RuralSettlement.get(s).state.simulationTicks-old.endClock;for(var town:t.state.towns.values())for(var p:town.prices){if(p.emptySince>=0)p.emptySince+=gap;if(p.richSince>=0)p.richSince+=gap;}for(var b:t.state.businesses.values()){if(b.phase>0)b.arrive+=gap;if(b.lastIncome>=0)b.lastIncome+=gap;}var run=new CityTrade.Run();run.ready=true;run.city=old.city;run.village=old.village;t.state.run=run;t.start(s);c.getSource().sendSuccess(()->Component.literal("沿现有家庭、货物和原有总资金继续观察30日，无重置或补款"),true);return 1;}))  .then(Commands.literal("status").executes(c->{var t=CityTrade.get(c.getSource().getServer());t.sample(c.getSource().getServer());t.write(c.getSource().getServer());c.getSource().sendSuccess(()->Component.literal(CityEconomy.JSON.toJson(t.state.run)),false);return 1;}))
  .then(Commands.literal("renew").executes(c->{var s=c.getSource().getServer();var t=CityTrade.get(s);CityEconomy.require(!t.state.run.running&&t.state.run.ready,"先暂停已有观察，再仅重开观察时钟");var old=t.state.run;try{var dir=s.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("city_settlements/finite-economy");java.nio.file.Files.copy(dir.resolve("latest.json"),dir.resolve("partial-"+old.startClock+".json"),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}catch(java.io.IOException ex){throw new IllegalArgumentException("不能保存前一片段，不重开",ex);}long ended=old.endClock>0?old.endClock:CityData.get(s).require(old.city).works.clock;long gap=Math.max(0,RuralSettlement.get(s).state.simulationTicks-ended);for(var town:t.state.towns.values())for(var price:town.prices){if(price.emptySince>=0)price.emptySince+=gap;if(price.richSince>=0)price.richSince+=gap;}for(var business:t.state.businesses.values()){if(business.phase>0)business.arrive+=gap;if(business.lastIncome>=0)business.lastIncome+=gap;}var r=new CityTrade.Run();r.ready=true;r.city=old.city;r.village=old.village;t.state.run=r;t.start(s);c.getSource().sendSuccess(()->Component.literal("仅观察时钟重开30日；人物、死亡、钱、物资原样接续，旧片段已保留"),true);return 1;}))
  .then(Commands.literal("report").executes(c->{var t=CityTrade.get(c.getSource().getServer());t.write(c.getSource().getServer());c.getSource().sendSuccess(()->Component.literal("world/city_settlements/finite-economy/latest.json"),false);return 1;}))
  .then(Commands.literal("pause").executes(c->{var s=c.getSource().getServer();var t=CityTrade.get(s);t.state.run.endClock=RuralSettlement.get(s).state.simulationTicks;t.state.run.endedAt=java.time.OffsetDateTime.now().toString();t.sample(s);t.state.run.running=false;for(var id:t.state.towns.keySet()){RuralSettlement.get(s).state.enabled.remove(id);CityData.get(s).require(id).works.enabled=false;}t.setDirty();t.write(s);c.getSource().sendSuccess(()->Component.literal("仅有限经济样板暂停；原村未改"),true);return 1;})));
 }
 static boolean block(ServerPlayer p,BlockPos pos,String kind){if(!Set.of("procurement","baker","supplier").contains(kind))return false;snapshot(p,"");return true;}
 static void request(ServerPlayer p,CityNetwork.Request r){try{RuralTools.editor(p);var t=CityTrade.get(p.server);if(r.op().equals("tradestart"))t.start(p.server);if(r.op().equals("tradeconfig")){CityEconomy.require(r.revision()==t.state.configRevision,"参数已变化，请刷新后再保存");var config=CityEconomy.JSON.fromJson(r.value(),CityTrade.Config.class);CityTrade.validate(config);t.state.config=config;t.state.configRevision++;t.setDirty();t.write(p.server);}snapshot(p,"");}catch(IllegalArgumentException ex){snapshot(p,ex.getMessage());}}
 static void snapshot(ServerPlayer p,String message){var t=CityTrade.get(p.server);var n=new CompoundTag();n.putBoolean("Trade",true);n.putString("Config",CityEconomy.JSON.toJson(t.state.config));n.putLong("ConfigRevision",t.state.configRevision);n.putString("Message",message);var run=t.state.run;n.putString("Status",run.running?"运行中":run.done?"30日观察已完成":"待启动");n.putDouble("Days",(RuralSettlement.get(p.server).state.simulationTicks-run.startClock)/24000.0);n.putString("Checks",run.checks.toString());StringBuilder rows=new StringBuilder();for(var b:t.state.businesses.values())rows.append(switch(b.kind){case "procurement"->"采购商";case "baker"->"烘焙坊";case "supplier"->"消费品工坊";case "supplier_helper"->"工坊工人";case "urban_farmer"->"城市农户";default->"农村头人";}).append(" 资金 ").append(CityEconomy.get(p.server).balance(b.account)).append(" ").append(b.status).append('\n');n.putString("Rows",rows.toString());PacketDistributor.sendToPlayer(p,new CityNetwork.Snapshot(n));}
 static UUID create(MinecraftServer s){var t=CityTrade.get(s);CityEconomy.require(!t.state.run.ready&&t.state.towns.isEmpty(),"已存在样板，不重置世界/账本");var l=s.overworld();var data=CityData.get(s);var origin=new BlockPos(10000,96,10000);var villageOrigin=origin.offset(160,0,0);var cityBounds=CityBounds.between(origin,origin.offset(79,8,63));var villageBounds=CityBounds.between(villageOrigin,villageOrigin.offset(127,8,79));data.checkBounds(null,l.dimension().location().toString(),cityBounds);data.checkBounds(null,l.dimension().location().toString(),villageBounds);
  // Explicit one-time construction reads chunks normally; no persistent force-load tickets.
  for(var bounds:List.of(cityBounds,villageBounds)){for(int x=bounds.min().getX()>>4;x<=bounds.max().getX()>>4;x++)for(int z=bounds.min().getZ()>>4;z<=bounds.max().getZ()>>4;z++)l.getChunk(x,z);for(int i=0;i<bounds.volume();i++)CityEconomy.require(l.getBlockState(bounds.at(i)).isAir(),"样板区非空，取消创建，未改原村");}
  var type=BuiltInRegistries.ENTITY_TYPE.get(ResourceLocation.parse("customnpcs:customnpc"));CityEconomy.require(type!=null,"需要联合服CustomNPCs");var city=data.create(UUID.randomUUID(),"有限经济·城",l.dimension().location().toString(),cityBounds);var village=data.create(city.owner,"有限经济·村",l.dimension().location().toString(),villageBounds);var d=RuralSettlement.get(s);var e=CityEconomy.get(s);for(var pair:List.of(city,village)){var town=new CityTrade.Town();town.city=pair.id;town.urban=pair==city;town.standardMultiplier=town.urban?1.5:1;t.state.towns.put(pair.id,town);for(int x=pair.bounds.min().getX();x<=pair.bounds.max().getX();x++)for(int z=pair.bounds.min().getZ();z<=pair.bounds.max().getZ();z++)l.setBlock(new BlockPos(x,96,z),Blocks.GRASS_BLOCK.defaultBlockState(),2);}
  var cityPeople=new ArrayList<RuralRules.Person>();for(int i=0;i<8;i++)cityPeople.add(person(s,city,origin.offset((i/2)*16+3,1,3),"城民"+(i+1),type));
  var cityFamilies=new ArrayList<RuralRules.Family>();for(int f=0;f<4;f++)cityFamilies.add(family(s,cityPeople.get(f*2),cityPeople.get(f*2+1)));var cityRoles=List.of("procurement","supplier","procurement","supplier_helper","baker","urban_farmer","artisan","");
  for(int i=0;i<8;i++){var p=cityPeople.get(i);String kind=cityRoles.get(i);var pos=origin.offset(3+i*8,1,20);if(kind.isEmpty())continue;var block=switch(kind){case "procurement"->RuralBlocks.GUILD.get();case "baker"->RuralBlocks.OVEN.get();case "urban_farmer"->RuralBlocks.SIFTER.get();case "artisan"->Blocks.CRAFTING_TABLE;default->RuralBlocks.SUPPLY.get();};job(s,city,p,pos,kind,block);if(kind.equals("artisan"))continue;var b=business(s,city,p,pos,kind);if(kind.equals("procurement"))seed(s,b.account,1000);else if(kind.equals("baker"))seed(s,b.account,500);else if(kind.equals("supplier"))seed(s,b.account,1000);else if(kind.equals("urban_farmer")){b.account=CityEconomy.person(p.id);b.listed[0].add(40,0);field(s,city,origin.offset(45,0,36));}}
  for(int f=0;f<4;f++){home(s,city,origin.offset(f*16,1,0),cityPeople.get(f*2).id,cityPeople.subList(f*2,f*2+2).stream().map(p->p.id).toList());boxes(s,city,cityFamilies.get(f),origin.offset(f*16,1,10),3,20);}
  for(int f=0;f<6;f++){int x=switch(f){case 3->0;case 4->96;case 5->64;default->f*16;};int z=f==3||f==4?32:0;var home=villageOrigin.offset(x,1,z);var husband=person(s,village,home.offset(2,0,2),"村民"+(f+1)+"夫",type);var wife=person(s,village,home.offset(3,0,2),"村民"+(f+1)+"妻",type);wife.female=true;var family=family(s,husband,wife);husband.spouse=wife.id;wife.spouse=husband.id;husband.marriage=wife.marriage=RuralRules.Marriage.FACTUAL;String kind=f<3?"farmer":f<5?"hunter":"merchant";var work=home.offset(2,0,6);job(s,village,husband,work,kind,f<3?RuralBlocks.SIFTER.get():f<5?RuralBlocks.HUNTER.get():RuralBlocks.DESK.get());job(s,village,wife,home.offset(4,0,6),"cook",RuralBlocks.STOVE.get());home(s,village,home,husband.id,List.of(husband.id,wife.id));boxes(s,village,family,home.offset(0,0,10),f==5?15:3,20);if(f<3)field(s,village,home.offset(5,-1,13));if(f>=3&&f<5)forest(s,villageOrigin.offset(x,0,50));if(f==5){var b=business(s,village,husband,work,"head");b.account=CityEconomy.person(husband.id);seed(s,b.account,500);RuralRules.put(d.stocks(family.id),false,60);}}
  for(var c:List.of(city,village)){var plan=CityMaintenance.get(s).state.cities.computeIfAbsent(c.id,k->new CityMaintenance.Plan());for(int i=0;i<c.bounds.volume();i++){var pos=c.bounds.at(i);if(l.getBlockState(pos).is(Blocks.WHEAT))plan.baseline.put(pos.asLong(),CityMaintenance.encode(l.getBlockState(pos)));}plan.enabled=true;plan.collective=false;c.works.clock=d.state.simulationTicks;c.works.day=d.state.simulationDay;c.works.nextDecay=c.works.clock+72000;c.works.nextSegment=c.works.clock+3000;c.works.nextMeal=c.works.clock+36000;c.works.finalized=true;c.works.enabled=false;c.works.resources.put("minecraft:oak_planks",256);c.works.resources.put("minecraft:crafting_table",4);for(int x=c.bounds.min().getX();x<=c.bounds.max().getX();x++)for(int z=c.bounds.min().getZ();z<=c.bounds.max().getZ();z++){var pos=new BlockPos(x,96,z);c.works.terrain.put(pos.asLong(),CityMaintenance.encode(l.getBlockState(pos)));}for(int n=0;n<c.bounds.volume();n++){var pos=c.bounds.at(n);if(!l.getBlockState(pos).isAir()&&CityWorks.at(c,pos.asLong())==null)c.works.terrain.put(pos.asLong(),CityMaintenance.encode(l.getBlockState(pos)));}}
  var artisan=cityPeople.get(6);var site=d.state.sites.values().stream().filter(v->artisan.id.equals(v.worker)).findFirst().orElseThrow();var building=UUID.randomUUID();var bounds=CityBounds.between(BlockPos.of(site.pos).offset(-1,0,-1),BlockPos.of(site.pos).offset(1,2,1));city.buildings.put(building,new CityRegistry.Building(building,"城市工坊","工坊",bounds));var house=CityHousing.house(city,building);house.configured=true;house.personal=false;house.workerLimit=1;house.workers.add(artisan.id);house.artisanWorkshop=true;house.production=false;house.baseline.put(site.pos,CityMaintenance.encode(Blocks.CRAFTING_TABLE.defaultBlockState()));var worker=CityMaintenance.get(s).state.workers.computeIfAbsent(artisan.id,k->new CityMaintenance.Worker());worker.city=city.id;worker.enabled=true;worker.artisan=true;worker.role="工匠";
  seed(s,CityEconomy.treasury(city.id),1000);for(int g=0;g<4;g++){var baker=t.state.businesses.values().stream().filter(b->b.kind.equals("baker")).findFirst().orElseThrow();if(g==1)baker.listed[1].add(24,0);}for(var c:List.of(city,village))d.state.enabled.remove(c.id);t.state.run.city=city.id;t.state.run.village=village.id;t.state.run.ready=true;CityEconomy.require(t.money(s)==6000,"初始资金应为6000");data.setDirty();d.setDirty();e.setDirty();CityMaintenance.get(s).setDirty();t.setDirty();t.write(s);return city.id;
 }
 static void seed(MinecraftServer s,String account,long n){var e=CityEconomy.get(s);e.state.accounts.merge(account,n,Long::sum);e.log(s.overworld().getGameTime(),"FINITE_INITIAL","outside_scenario",account,n,"有限样板一次性初始预算，之后无补款");}
 static RuralRules.Person person(MinecraftServer s,CityData.City c,BlockPos pos,String name,net.minecraft.world.entity.EntityType<?> type){var entity=type.create(s.overworld());CityEconomy.require(entity instanceof Mob,"NPC创建失败");entity.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5,0,0);entity.setCustomName(Component.literal(name));((Mob)entity).setNoAi(true);((Mob)entity).setPersistenceRequired();s.overworld().addFreshEntity(entity);c.residents.add(entity.getUUID());var p=RuralSettlement.get(s).enroll(s,c,entity.getUUID(),name);p.trainedHours=10;return p;}
 static RuralRules.Family family(MinecraftServer s,RuralRules.Person a,RuralRules.Person b){var d=RuralSettlement.get(s);var f=d.state.families.get(a.family);var old=d.state.families.get(b.family);old.members.remove(b.id);d.state.families.remove(old.id);RuralRules.admit(f,b,d.state.people);return f;}
 static void job(MinecraftServer s,CityData.City c,RuralRules.Person p,BlockPos pos,String kind,Block block){s.overworld().setBlock(pos,block.defaultBlockState(),3);var d=RuralSettlement.get(s);var site=d.state.sites.computeIfAbsent(RuralSettlement.key(c.id,pos.asLong()),k->new RuralSettlement.Site());site.city=c.id;site.worker=p.id;site.pos=pos.asLong();site.kind=kind.equals("urban_farmer")?"farmer":kind.equals("supplier_helper")?"supplier":kind;site.present=true;site.expectedBlock=BuiltInRegistries.BLOCK.getKey(block).toString();p.role=switch(kind){case "farmer","urban_farmer"->RuralRules.Role.FARMER;case "cook"->RuralRules.Role.COOK;case "hunter"->RuralRules.Role.HUNTER;case "merchant"->RuralRules.Role.MERCHANT;case "artisan"->RuralRules.Role.ARTISAN;case "baker"->RuralRules.Role.BAKER;case "procurement"->RuralRules.Role.PROCUREMENT;default->RuralRules.Role.SUPPLIER;};WorkHours.config(s,p.id);if(!kind.equals("artisan")){UUID building=UUID.randomUUID();c.buildings.put(building,new CityRegistry.Building(building,kind,"工坊",CityBounds.between(pos,pos)));var h=CityHousing.house(c,building);h.configured=true;h.personal=true;h.owner=p.id;h.workerLimit=1;h.workers.add(p.id);h.production=false;h.baseline.put(pos.asLong(),CityMaintenance.encode(block.defaultBlockState()));}}
 static CityTrade.Business business(MinecraftServer s,CityData.City c,RuralRules.Person p,BlockPos pos,String kind){var b=new CityTrade.Business();b.id=UUID.randomUUID();b.city=c.id;b.worker=p.id;b.site=pos.asLong();b.kind=kind;b.account="trade:"+b.id;CityTrade.get(s).state.businesses.put(b.id,b);return b;}
 static void boxes(MinecraftServer s,CityData.City c,RuralRules.Family f,BlockPos start,int count,int initial){var d=RuralSettlement.get(s);for(int i=0;i<count;i++){var pos=start.offset(i%5,0,i/5);s.overworld().setBlock(pos,RuralBlocks.CHEST.get().defaultBlockState(),3);var b=d.state.boxes.computeIfAbsent(RuralSettlement.key(c.id,pos.asLong()),k->new RuralSettlement.Box());b.city=c.id;b.pos=pos.asLong();b.linked=true;b.stock.family=f.id;b.site=d.state.sites.values().stream().filter(v->f.members.contains(v.worker)).findFirst().orElseThrow().pos;((RuralBlocks.Link)s.overworld().getBlockEntity(pos)).offset=BlockPos.of(b.site).subtract(pos);}RuralRules.put(d.stocks(f.id),true,initial/2);RuralRules.put(d.stocks(f.id),false,initial-initial/2);}
 static void home(MinecraftServer s,CityData.City c,BlockPos pos,UUID owner,List<UUID> residents){var bounds=CityBounds.between(pos,pos.offset(6,3,5));UUID id=UUID.randomUUID();c.buildings.put(id,new CityRegistry.Building(id,"测试住宅","住宅",bounds));var h=CityHousing.house(c,id);h.configured=true;h.personal=true;h.owner=owner;h.beds=2;h.residents.addAll(residents);h.production=false;for(int x=0;x<=6;x++)for(int z=0;z<=5;z++)if(x==0||x==6||z==0||z==5){var p=pos.offset(x,0,z);s.overworld().setBlock(p,Blocks.OAK_PLANKS.defaultBlockState(),2);h.baseline.put(p.asLong(),CityMaintenance.encode(Blocks.OAK_PLANKS.defaultBlockState()));}var door=pos.offset(3,0,0);s.overworld().setBlock(door,Blocks.AIR.defaultBlockState(),2);h.baseline.remove(door.asLong());}
 static void field(MinecraftServer s,CityData.City c,BlockPos start){s.overworld().setBlock(start.offset(2,0,-1),Blocks.WATER.defaultBlockState(),2);for(int x=0;x<5;x++)for(int z=0;z<4;z++){var p=start.offset(x,0,z);s.overworld().setBlock(p,Blocks.FARMLAND.defaultBlockState().setValue(FarmBlock.MOISTURE,7),2);s.overworld().setBlock(p.above(),Blocks.WHEAT.defaultBlockState().setValue(CropBlock.AGE,7),2);}}
 static void forest(MinecraftServer s,BlockPos origin){for(int x:new int[]{3,11})for(int z:new int[]{3,11}){for(int y=1;y<=5;y++)s.overworld().setBlock(origin.offset(x,y,z),Blocks.OAK_LOG.defaultBlockState(),2);for(int dx=-3;dx<=3;dx++)for(int dz=-3;dz<=3;dz++)for(int y=5;y<=6;y++)if(dx!=0||dz!=0||y==6)s.overworld().setBlock(origin.offset(x+dx,y,z+dz),Blocks.OAK_LEAVES.defaultBlockState().setValue(LeavesBlock.PERSISTENT,true),2);}var d=RuralSettlement.get(s);for(int x=origin.getX()>>4;x<=(origin.getX()+15)>>4;x++)for(int z=origin.getZ()>>4;z<=(origin.getZ()+15)>>4;z++){var cell=HunterForest.inspect(s.overworld(),x,z);if(cell!=null)d.state.forest.put(HunterForest.key(s.overworld().dimension().location().toString(),x,z),cell);}}
}
